/*
 * Cyrillic glyphs for 'Vx Roboto', from the same Roboto release (v2.137, 2017)
 * as the Latin faces in ./roboto.ts, which are a Basic Latin subset and have no
 * Cyrillic at all. Without these, every Cyrillic character falls back to
 * whatever sans-serif the machine has installed, so Russian text renders in a
 * different typeface from the digits and Latin abbreviations next to it.
 *
 * Declared on the same family with a `unicode-range`, so the browser uses these
 * faces only for the characters listed and the existing Latin faces (and their
 * rendering) are untouched.
 *
 * Source: https://github.com/google/fonts/tree/724bf98e9f/apache/roboto
 * (the commit that added Roboto v2.137). Regenerate with fontTools:
 *
 *   pyftsubset Roboto-<Face>.ttf --unicodes="U+0301, U+0400-0486, U+0488-0513, U+2116" \
 *     --layout-features='*' --name-IDs='*' --notdef-outline --flavor=woff2
 *
 * then set the hhea ascent/descent/lineGap, OS/2 typo ascender/descender/line
 * gap and OS/2 win ascent/descent of each subset to the values in the
 * ./roboto.ts faces (2163/-595/0; 1536/-512/0; 2163/595),
 * which Font Squirrel adjusted when those were generated, so that a line mixing
 * Cyrillic and Latin keeps a single line box.
 */

import { css } from 'styled-components';

export const ROBOTO_CYRILLIC_REGULAR_FONT_DECLARATIONS = css`
  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 100;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }

  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 300;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }

  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 400;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }

  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 500;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }

  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 700;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }

  @font-face {
    font-family: 'Vx Roboto';
    font-weight: 900;
    font-style: normal;
    unicode-range: U+0301, U+0400-0486, U+0488-0513, U+2116;
    src: url('data:font/woff2;base64,')
      format('woff2');
  }
`;

